import json, unittest
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from components.contact_profiles.work import compute

class TestProfiles(unittest.TestCase):
    def test_shape_and_collapse(self):
        payload = {"batches": [[
            {"email": " A@X.COM ", "name": "  Alice   Bob ", "city": "  New   York  ", "source": "web", "time": 8}
        ]]}
        out = compute(payload)
        self.assertEqual(len(out), 1)
        self.assertEqual(len(out[0]), 1)
        row = out[0][0]
        self.assertEqual(set(row.keys()), {"name", "city", "source", "time"})
        self.assertEqual(row["name"], "Alice Bob")
        self.assertEqual(row["city"], "New York")
        self.assertEqual(row["source"], "web")
        self.assertEqual(row["time"], 8)

    def test_empty_fields(self):
        payload = {"batches": [[
            {"email": "a@x.com", "name": "   ", "city": "", "source": "s", "time": 0}
        ]]}
        row = compute(payload)[0][0]
        self.assertEqual(row["name"], "")
        self.assertEqual(row["city"], "")

    def test_order_preserved(self):
        payload = {"batches": [[
            {"email": "a", "name": "A", "city": "C", "source": "s1", "time": 1},
            {"email": "b", "name": "B", "city": "D", "source": "s2", "time": 2},
        ], [
            {"email": "c", "name": "E", "city": "F", "source": "s3", "time": 3},
        ]]}
        out = compute(payload)
        self.assertEqual([r["name"] for r in out[0]], ["A", "B"])
        self.assertEqual([r["name"] for r in out[1]], ["E"])

if __name__ == "__main__":
    unittest.main()
