        payload = {
            "batches": [
                [
                    {"email": " A@EXAMPLE.COM ", "name": "Alice", "city": "", "source": "web", "time": 8},
                    {"email": "b@example.com", "name": "Bob", "city": "X", "source": "cli", "time": 9},
                ],
                [
                    {"email": "  C@Example.COM  ", "name": "C", "city": "", "source": "web", "time": 10},
                ],
            ]
        }
        self.assertEqual(
            compute(payload),
            [["a@example.com", "b@example.com"], ["c@example.com"]],
        )

    def test_empty_batches(self):
        self.assertEqual(compute({"batches": []}), [])


if __name__ == "__main__":
    unittest.main()

